        r = SandboxedEnvironment(undefined=StrictUndefined).from_string(src).render(x=lambda: 1)
        print('NOT BLOCKED:', src, '->', repr(r))
    except Exception as ex:
        print('blocked:', type(ex).__name__, '|', src)
try: SandboxedEnvironment().from_string('{{ range(200000)|list|length }}').render()
except Exception as ex: print('range cap:', type(ex).__name__, ex)
i = ImmutableSandboxedEnvironment()
for src in ['{{ l.append(1) }}', '{{ d.clear() }}', '{{ s.add(1) }}']:
    try: i.from_string(src).render(l=[], d={}, s=set()); print('NOT BLOCKED:', src)
